import { useState, useCallback } from "react";
import { loadSave, getDefaultSave, saveSave } from "~/lib/persistence";
import type { SaveData } from "~/lib/persistence";

/**
 * Centralized save-data primitive — the single initialization coordinator
 * for all hooks that need access to persisted save state.
 *
 * SSR-safe: falls back to `getDefaultSave()` on the server.
 *
 * If save validation, migration logic, or error recovery is ever needed,
 * this is the ONE place to add it instead of patching every consumer.
 */
export function useSave() {
  const [save, setSave] = useState<SaveData>(() =>
    typeof window !== "undefined" ? loadSave() : getDefaultSave()
  );

  /**
   * Read-modify-write helper that loads a fresh copy from storage,
   * applies the updater, persists the result, and syncs React state.
   */
  const updateSave = useCallback(
    (updater: (current: SaveData) => SaveData) => {
      const fresh = loadSave();
      const updated = updater(fresh);
      saveSave(updated);
      setSave(updated);
    },
    [],
  );

  /**
   * Re-read save from storage into React state.
   * Use when an external call (e.g. `completeLevel`) wrote to storage
   * outside of `updateSave`.
   */
  const refreshSave = useCallback(() => {
    setSave(loadSave());
  }, []);

  return { save, setSave, refreshSave, updateSave } as const;
}

/**
 * Shared geometry constants for the rainbow easter-egg arc.
 *
 * These are consumed by both the RainbowArc presentation component
 * (SVG viewBox) and the useRainbowEasterEgg hook (hit-detection math).
 * Extracted to a lib-level module so neither zone imports from the other.
 */

/** SVG viewBox width for the rainbow arc. */
export const SVG_WIDTH = 320;

/** SVG viewBox height for the rainbow arc. */
export const SVG_HEIGHT = 140;

/** Vertical center of the arc as a ratio of SVG_HEIGHT (used for hit-detection). */
export const ARC_CENTER_Y_RATIO = 0.78;

import { useSave } from "~/hooks/useSave";
import { getAllLevelIds, getAllWorlds, getLevelsForWorld } from "~/engine";
import type { LevelData, WorldData } from "~/engine";
import { isLevelUnlockedWithSave } from "~/lib/persistence";
import type { SaveData } from "~/lib/persistence";

/**
 * Encapsulates save-data loading, level-unlock checks, and world/level
 * queries for the worlds route.
 *
 * This is the sole gateway to engine world/level data for routes —
 * routes should not import engine query functions directly.
 *
 * Delegates persistence initialisation to `useSave` so validation,
 * migration, and error recovery live in a single coordinator.
 */
export function useWorldSession() {
  const { save, setSave, updateSave } = useSave();

  const allLevelIds = getAllLevelIds();
  const worlds = getAllWorlds();

  function isLevelUnlocked(levelId: string): boolean {
    return isLevelUnlockedWithSave(save, levelId, allLevelIds);
  }

  function getClovers(levelId: string): number {
    return save.completedLevels[levelId] || 0;
  }

  function getLevels(worldId: number): LevelData[] {
    return getLevelsForWorld(worldId);
  }

  return {
    save,
    setSave,
    updateSave,
    worlds,
    isLevelUnlocked,
    getClovers,
    getLevels,
  };
}

export type { SaveData, WorldData };

